/// Single-color SVG icons, tinted at runtime with `AppIcon`. Generated by
/// `tool/figma/build_icons.py` from the Figma exports.
abstract final class AppIcons {
  static const back = 'assets/icons/back.svg';
  static const check = 'assets/icons/check.svg';
  static const help = 'assets/icons/help.svg';
  static const lock = 'assets/icons/lock.svg';
  static const mail = 'assets/icons/mail.svg';
  static const user = 'assets/icons/user.svg';
}
